-- <<<<<< 08-seed.sql <<<<<<

-- >>>>>> 09-fix-reviews-author-id.sql (1.1 kB) >>>>>>
-- =============================================================================
-- Step 09 — Add missing author_id column to public.reviews
-- =============================================================================
-- Some Supabase projects have a public.reviews table that was created before
-- step 02 introduced the author_id column. The RLS policies and the Next.js
-- client code both reference reviews.author_id, so the column is required.
--
-- After step 10 (standardize ids to uuid) the column type is uuid. If you
-- haven't run step 10 yet on a project where user_profiles.id is text, you
-- can run this step with type text instead — but the more durable fix is
-- to run step 10 once and use the uuid variant.
--
-- This step is idempotent and safe to re-run. Existing rows get NULL.
-- =============================================================================

alter table public.reviews
  add column if not exists author_id uuid references public.user_profiles(id) on delete set null;

create index if not exists idx_reviews_author_id on public.reviews (author_id);
-- <<<<<< 09-fix-reviews-author-id.sql <<<<<<

-- >>>>>> 10-standardize-ids-to-uuid.sql (9.5 kB) >>>>>>
-- =============================================================================
-- Step 10 — Standardize all id columns to uuid
-- =============================================================================
-- This project's tables were originally created with text id columns
-- (because auth.uid() used to return text on this Supabase instance).
-- We're migrating everything to uuid to match the standard Supabase
-- schema and remove the need for ::text casts in RLS.
--
-- This step is fully idempotent and safe to re-run on any state:
--   * If a column is already uuid, ALTER COLUMN … TYPE uuid USING col::uuid
--     is a no-op (Postgres skips the rewrite when types match).
--   * If a FK already exists with the right name, drop constraint
--     if exists is a no-op; add constraint below either succeeds or
--     is a no-op if the same constraint already exists.
--   * If a column has non-uuid text in it, the USING col::uuid cast
--     will fail loudly so we can fix the data manually.
--
-- Pre-conditions (verified before this step is shipped):
--   * Every row in public.user_profiles.id is a valid UUID string
--   * The same is true for profiles.owner_id, complaints.author_id,
--     complaints.target_user_id, notifications.recipient_id and
--     reviews.author_id (confirmed via information_schema.columns +
--     sample SELECTs)
--   * auth.users.id is already uuid (we never touch that table)
--
-- Order matters:
--   1. Drop every RLS policy that references any of the columns we are
--      about to convert. Postgres refuses to ALTER a column that is
--      referenced by a policy (ERROR 0A000), so we must drop them first.
--      step 05 will recreate them with the new (uuid) types.
--   2. Drop the convenience views that SELECT from those columns for the
--      same reason (Postgres raises "cannot alter type of a column used
--      by a view or rule" otherwise). step 06 will recreate them after
--      the type change.
--   3. Drop every FK that points at user_profiles.id or at any of the
--      columns we are about to convert, so the ALTER COLUMN can run
--      without the type-mismatch error described in the
--      "reviews_author_id_fkey cannot be implemented" issue.
--   4. ALTER COLUMN with USING col::uuid (idempotent: same-type ALTER
--      is a no-op).
--   5. Recreate the FKs as NOT VALID (so the conversion is fast) and
--      VALIDATE them all at the end.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 0a) Drop every RLS policy in the public schema. We don't try to
--     limit this to specific tables because policies can reference
--     columns from other tables via sub-queries (e.g.
--     'certificates owner write' depends on profiles.owner_id through
--     'exists (select … p.owner_id = auth.uid())'), and Postgres
--     blocks ALTER on any column that appears in any policy on any
--     table in the schema. step 05 will recreate them at the end of
--     the migration.
-- ---------------------------------------------------------------------------
do $$
declare
  pol record;
begin
  for pol in
    select schemaname, tablename, policyname
    from pg_policies
    where schemaname = 'public'
  loop
    execute format('drop policy if exists %I on public.%I', pol.policyname, pol.tablename);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 0b) Drop the convenience views defined in step 06.
-- ---------------------------------------------------------------------------
drop view if exists public.v_public_profiles;
drop view if exists public.v_all_profiles;
drop view if exists public.v_user_directory;
drop view if exists public.v_current_donations;

-- ---------------------------------------------------------------------------
-- 0c) Drop every FK that points at user_profiles.id or at any of the
--     columns we are about to convert. We don't try to be clever about
--     which FKs exist; we drop the 5 known names and recreate them at
--     the end. drop constraint if exists makes each line a no-op when
--     the FK was already dropped in a previous run.
-- ---------------------------------------------------------------------------
alter table public.profiles      drop constraint if exists profiles_owner_id_fkey;
alter table public.reviews       drop constraint if exists reviews_author_id_fkey;
alter table public.complaints    drop constraint if exists complaints_author_id_fkey;
alter table public.complaints    drop constraint if exists complaints_target_user_id_fkey;
alter table public.notifications drop constraint if exists notifications_recipient_id_fkey;

-- ---------------------------------------------------------------------------
-- 1) user_profiles.id → uuid
--     ALTER COLUMN … TYPE uuid USING id::uuid is a no-op when the column
--     is already uuid, so this is safe on a partially-migrated project.
-- ---------------------------------------------------------------------------
alter table public.user_profiles
  alter column id type uuid using id::uuid;

-- ---------------------------------------------------------------------------
-- 2) profiles.owner_id → uuid
-- ---------------------------------------------------------------------------
alter table public.profiles
  alter column owner_id type uuid using owner_id::uuid;
alter table public.profiles
  add constraint profiles_owner_id_fkey
  foreign key (owner_id) references public.user_profiles(id) on delete cascade
  not valid;

-- ---------------------------------------------------------------------------
-- 3) reviews.author_id → uuid
-- ---------------------------------------------------------------------------
alter table public.reviews
  alter column author_id type uuid using author_id::uuid;
alter table public.reviews
  add constraint reviews_author_id_fkey
  foreign key (author_id) references public.user_profiles(id) on delete set null
  not valid;

-- ---------------------------------------------------------------------------
-- 4) complaints.author_id + target_user_id → uuid
-- ---------------------------------------------------------------------------
alter table public.complaints
  alter column author_id     type uuid using author_id::uuid;
alter table public.complaints
  alter column target_user_id type uuid using target_user_id::uuid;
alter table public.complaints
  add constraint complaints_author_id_fkey
  foreign key (author_id) references public.user_profiles(id) on delete cascade
  not valid;
alter table public.complaints
  add constraint complaints_target_user_id_fkey
  foreign key (target_user_id) references public.user_profiles(id) on delete set null
  not valid;

-- ---------------------------------------------------------------------------
-- 5) notifications.recipient_id → uuid
-- ---------------------------------------------------------------------------
alter table public.notifications
  alter column recipient_id type uuid using recipient_id::uuid;
alter table public.notifications
  add constraint notifications_recipient_id_fkey
  foreign key (recipient_id) references public.user_profiles(id) on delete cascade
  not valid;

-- ---------------------------------------------------------------------------
-- 6) Validate the FKs we just re-added. VALIDATE CONSTRAINT is a no-op
--    if the constraint is already validated, so this is safe on a
--    project where these FKs already existed.
-- ---------------------------------------------------------------------------
alter table public.profiles      validate constraint profiles_owner_id_fkey;
alter table public.reviews       validate constraint reviews_author_id_fkey;
alter table public.complaints    validate constraint complaints_author_id_fkey;
alter table public.complaints    validate constraint complaints_target_user_id_fkey;
alter table public.notifications validate constraint notifications_recipient_id_fkey;

-- ---------------------------------------------------------------------------
-- 7) Recreate the convenience views (same definitions as step 06, but
--    with the ::text casts removed now that the join keys are uuid).
-- ---------------------------------------------------------------------------
create or replace view public.v_public_profiles
  with (security_invoker = true) as
select
  p.*,
  u.email        as owner_email,
  u.is_blocked   as owner_is_blocked
from public.profiles p
left join public.user_profiles u on u.id = p.owner_id
where not (p.is_hidden or p.is_banned);

create or replace view public.v_all_profiles
  with (security_invoker = true) as
select
  p.*,
  u.email        as owner_email,
  u.is_blocked   as owner_is_blocked
from public.profiles p
left join public.user_profiles u on u.id = p.owner_id;

create or replace view public.v_user_directory
  with (security_invoker = true) as
select
  u.id,
  u.email,
  u.full_name,
  u.avatar_url,
  u.is_admin,
  u.is_blocked,
  u.created_at,
  coalesce(c.profiles_total, 0) as profile_count,
  coalesce(c.hidden_total, 0)   as hidden_count
from public.user_profiles u
left join (
  select
    owner_id,
    count(*)                          as profiles_total,
    count(*) filter (where is_hidden) as hidden_total
  from public.profiles
    group by owner_id
) c on c.owner_id = u.id;

create or replace view public.v_current_donations
  with (security_invoker = true) as
select
  coalesce(sum(amount), 0)::numeric(12,2) as total_rub,
  count(*)                                as donations_count
from public.donations
where received_at >= date_trunc('month', now() at time zone 'Europe/Moscow')
  and received_at <  date_trunc('month', now() at time zone 'Europe/Moscow') + interval '1 month';
-- <<<<<< 10-standardize-ids-to-uuid.sql <<<<<<

-- >>>>>> 11-profiles-rls-and-count.sql (7.3 kB) >>>>>>
-- =============================================================================
-- Step 11 — Fix profiles RLS to hide other users' personal profiles, and
--           add a server-side profile_count view for the admin panel.
-- =============================================================================
-- Run AFTER step 10. Idempotent.
--
-- Why this step exists:
--   The previous RLS policy "profiles public read" was:
--
--     using (
--       not (is_hidden or is_banned)
--       or auth.uid()::text = owner_id::text
--       or is_admin_email()
--     );
--
--   That means EVERYONE could SELECT every non-hidden / non-banned
--   profile, including other users' personal profiles (is_personal=true).
--   The UI happened to filter them out client-side, but a curious user
--   could read them straight from the database with curl + the anon key.
--   Worse, the Next.js client was caching them in localStorage, so they
--   leaked across sessions and across browsers (the "phantom profile"
--   bug).
--
--   The fix is to enforce the same rule on the server that we wanted on
--   the client: only the owner, the admin, and no one else can see a
--   personal profile. Non-personal profiles (specialists, public
--   listings) stay visible to everyone as before.
--
--   We also add a SQL view that returns user_profiles with a
--   server-computed `profile_count`. The admin panel reads from this
--   view instead of counting client-side, so the count is always
--   correct (and always >= 1 for users with a personal profile).
-- =============================================================================


-- ---------------------------------------------------------------------------
-- 1) Tighten the public-read RLS policy to hide other users' personal
--    profiles. The owner and the admin still see them.
-- ---------------------------------------------------------------------------
drop policy if exists "profiles public read" on public.profiles;
create policy "profiles public read"
  on public.profiles for select
  using (
    -- Anyone can see a non-personal profile that is not hidden / banned.
    (not is_personal and not (is_hidden or is_banned))
    -- The owner can always see their own rows, including their personal
    -- profile and any hidden / banned rows of theirs.
    or auth.uid()::text = owner_id::text
    -- Admins can see everything for moderation purposes.
    or is_admin_email()
  );


-- ---------------------------------------------------------------------------
-- 2) View: user_profiles with a server-computed profile_count.
--    Uses security_invoker = true so the calling user's RLS still applies
--    when they query the view (admins see real counts for everyone,
--    regular users would only see their own row through the underlying
--    user_profiles RLS — though in practice this view is only used by
--    the admin panel).
-- ---------------------------------------------------------------------------
create or replace view public.v_users_with_profile_count
  with (security_invoker = true) as
select
  u.id,
  u.email,
  u.full_name,
  u.avatar_url,
  u.is_admin,
  u.is_blocked,
  u.created_at,
  u.settlement,
  coalesce(c.profiles_total, 0) as profile_count,
  coalesce(c.hidden_total, 0)   as hidden_count
from public.user_profiles u
left join (
  select
    owner_id,
    count(*)                          as profiles_total,
    count(*) filter (where is_hidden or is_banned) as hidden_total
  from public.profiles
  where owner_id is not null
  group by owner_id
) c on c.owner_id = u.id;

comment on view public.v_users_with_profile_count is
  'user_profiles joined with a server-computed count of their profiles. '
  'Used by the admin panel. Read it with the service role to bypass '
  'user_profiles RLS for everyone, or as a regular user to see only '
  'your own row.';


-- ---------------------------------------------------------------------------
-- 3) Convenience RPC: create a personal profile for the calling user
--    if one doesn't already exist. Returns the existing row when
--    present (idempotent). Runs with security definer so it can
--    insert into profiles on behalf of the user without us having to
--    duplicate the owner-insert RLS logic in the application.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_personal_profile(
  p_full_name text,
  p_avatar_url text default '',
  p_phone text default ''
)
returns public.profiles
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_existing public.profiles;
  v_personal_id text;
  v_row public.profiles;
begin
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  v_personal_id := 'personal-' || v_user_id::text;

  -- Idempotency: if the canonical personal row already exists,
  -- return it. This is the only row we keep; we never spawn
  -- duplicates (the previous bug).
  select * into v_existing
    from public.profiles
   where id = v_personal_id;
  if found then
    return v_existing;
  end if;

  -- Defensive: if there are OTHER is_personal=true rows for this
  -- owner (e.g. created by an older client), we still don't error
  -- — we just create the canonical one alongside. The admin can
  -- clean up duplicates later.
  insert into public.profiles (
    id,
    owner_id,
    full_name,
    avatar_url,
    is_specialist,
    is_personal,
    bio,
    workplace_address,
    workplace_coords,
    phone,
    hide_phone,
    same_as_phone_whatsapp,
    settlement
  ) values (
    v_personal_id,
    v_user_id,
    coalesce(nullif(trim(p_full_name), ''), 'Житель Даймохк'),
    coalesce(p_avatar_url, ''),
    false,
    true,
    'Житель Даймохк. Личная анкета.',
    'Даймохк',
    '{"lat":43.288024,"lng":45.298989}'::jsonb,
    coalesce(p_phone, ''),
    true,
    false,
    'Самашки'
  )
  returning * into v_row;

  return v_row;
end;
$$;

revoke all on function public.ensure_personal_profile(text, text, text) from public;
grant execute on function public.ensure_personal_profile(text, text, text) to authenticated;

comment on function public.ensure_personal_profile(text, text, text) is
  'Create the canonical personal profile (id = personal-<auth.uid()>) '
  'for the calling user if it does not already exist. Idempotent: '
  'returns the existing row when present. Used by the Next.js client '
  'as a single round-trip replacement for the previous in-memory '
  'auto-create flow.';


-- ---------------------------------------------------------------------------
-- 4) Convenience RPC: a server-side view of profiles for a given
--    owner (used by the admin panel to list a user's questionnaires).
--    Runs with security definer so the admin can list any user's
--    profiles without us having to grant admins a special SELECT
--    bypass.
-- ---------------------------------------------------------------------------
create or replace function public.list_profiles_for_owner(p_owner_id uuid)
returns setof public.profiles
language sql
security definer
set search_path = public
stable
as $$
  select * from public.profiles where owner_id = p_owner_id
  order by is_personal desc, created_at desc;
$$;

revoke all on function public.list_profiles_for_owner(uuid) from public;
grant execute on function public.list_profiles_for_owner(uuid) to authenticated;
-- <<<<<< 11-profiles-rls-and-count.sql <<<<<<

-- >>>>>> 12-onboarding-trigger.sql (5.8 kB) >>>>>>
-- =============================================================================
-- Step 12 — Auto-create user_profiles + personal profile on signup
-- =============================================================================
-- Run AFTER step 11. Idempotent.
--
-- Why this step exists:
--   Before this step, the personal profile was created from the Next.js
--   client via /api/account/ensure-personal-profile. That worked in
--   theory, but had two problems:
--
--     1) If the user never opened the app, they had no user_profiles
--        row. The admin panel would not see them in the user list,
--        and the view v_users_with_profile_count would not return
--        them either.
--
--     2) If the client failed to call ensure-personal-profile (the
--        RPC was missing because step 11 hadn't been applied, for
--        example), the user had a user_profiles row but no
--        personal profile. Their profileCount stayed at 0.
--
--   The canonical Supabase fix for both is to put the onboarding
--   logic on the server, in an AFTER INSERT trigger on auth.users.
--   The trigger fires for every signup (Google OAuth, magic link,
--   email/password, etc.) and is the documented pattern in
--   supabase.com/docs/guides/auth/managing-user-data.
--
--   This step also backfills user_profiles and the personal profile
--   for any auth.users rows that already exist at the time of
--   execution, so admins that ran the project before this trigger
--   was added will get their personal profiles retroactively.
-- =============================================================================


-- ---------------------------------------------------------------------------
-- 1) A single SECURITY DEFINER function that handles all the onboarding
--    work: create user_profiles if missing, create the canonical
--    personal profile if missing. Both inserts go through the
--    SECURITY DEFINER role, which bypasses RLS so the trigger
--    doesn't get tangled up in self-insert RLS policies.
-- ---------------------------------------------------------------------------
create or replace function public.handle_new_auth_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_full_name text;
  v_avatar_url text;
  v_phone text;
  v_personal_id text;
  v_is_admin boolean;
begin
  v_full_name := coalesce(
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'name',
    ''
  );
  v_avatar_url := coalesce(new.raw_user_meta_data->>'avatar_url', '');
  v_phone := coalesce(new.phone, '');
  v_personal_id := 'personal-' || new.id::text;
  v_is_admin := lower(coalesce(new.email, '')) in (
    'mr.hamzik1026@gmail.com',
    'nabis95@gmail.com'
  );

  -- 1a) Create the user_profiles row if it doesn't exist.
  --     ON CONFLICT DO NOTHING is idempotent: re-running the
  --     trigger for the same user is a no-op.
  insert into public.user_profiles (
    id, email, full_name, avatar_url, phone, is_admin
  ) values (
    new.id, new.email, v_full_name, v_avatar_url, v_phone, v_is_admin
  )
  on conflict (id) do nothing;

  -- 1b) Create the canonical personal profile if it doesn't exist.
  --     Same idempotency trick.
  insert into public.profiles (
    id,
    owner_id,
    full_name,
    avatar_url,
    is_specialist,
    is_personal,
    bio,
    workplace_address,
    workplace_coords,
    phone,
    hide_phone,
    same_as_phone_whatsapp,
    settlement
  ) values (
    v_personal_id,
    new.id,
    v_full_name,
    v_avatar_url,
    false,
    true,
    'Житель Даймохк. Личная анкета.',
    'Даймохк',
    '{"lat":43.288024,"lng":45.298989}'::jsonb,
    v_phone,
    true,
    false,
    'Самашки'
  )
  on conflict (id) do nothing;

  return new;
end;
$$;

-- The trigger function runs as SECURITY DEFINER (the table owner)
-- because we need to bypass RLS when inserting the new rows on
-- behalf of the new user. Without this, the "user_profiles self
-- insert" and "profiles owner insert" RLS policies would block the
-- inserts (because auth.uid() is the new user, but the role
-- executing the trigger is the function owner, not the new user).
-- We grant execute only to the postgres role, which is what the
-- trigger uses to invoke the function.

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_auth_user();


-- ---------------------------------------------------------------------------
-- 2) Backfill: every auth.users row that doesn't yet have a
--    user_profiles entry gets one; every auth.users row that
--    doesn't yet have a personal-<id> profile gets one.
--    Safe to re-run: ON CONFLICT DO NOTHING everywhere.
-- ---------------------------------------------------------------------------
insert into public.user_profiles (id, email, full_name, avatar_url, phone, is_admin)
select
  au.id,
  au.email,
  coalesce(au.raw_user_meta_data->>'full_name', au.raw_user_meta_data->>'name', ''),
  coalesce(au.raw_user_meta_data->>'avatar_url', ''),
  coalesce(au.phone, ''),
  lower(coalesce(au.email, '')) in (
    'mr.hamzik1026@gmail.com', 'nabis95@gmail.com'
  )
from auth.users au
on conflict (id) do nothing;

insert into public.profiles (
  id, owner_id, full_name, avatar_url, is_specialist, is_personal,
  bio, workplace_address, workplace_coords, phone, hide_phone,
  same_as_phone_whatsapp, settlement
)
select
  'personal-' || au.id::text,
  au.id,
  coalesce(au.raw_user_meta_data->>'full_name', au.raw_user_meta_data->>'name', 'Житель Даймохк'),
  coalesce(au.raw_user_meta_data->>'avatar_url', ''),
  false,
  true,
  'Житель Даймохк. Личная анкета.',
  'Даймохк',
  '{"lat":43.288024,"lng":45.298989}'::jsonb,
  coalesce(au.phone, ''),
  true,
  false,
  'Самашки'
from auth.users au
on conflict (id) do nothing;
-- <<<<<< 12-onboarding-trigger.sql <<<<<<

